sys_script_include.script:
var TrainingUtils = Class.create();
TrainingUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    checkDuplicateSchedule: function() {
        //gs.info("ryuki: entrou na funcao");
        var training = this.getParameter('sysparm_training');
        var startDate = this.getParameter('sysparm_start_date');
        //gs.info("ryuki curso: " + training);
        //gs.info("ryuki data: "+ startDate);
        var grSchedule = new GlideRecord("x_1092529_traini_0_training_schedule");
        grSchedule.addEncodedQuery("training=" + training + "^training_dateON" + startDate + "@javascript:gs.dateGenerate('" + startDate + "','start')@javascript:gs.dateGenerate('" + startDate + "','end')");
        grSchedule.setLimit(1);
        grSchedule.query();

        if (grSchedule.next()) {
            // gs.info("ryuki: entrou no if");
            // gs.info("ryuki: data do gliderecord: "+ grSchedule.training_date);
            return true;
        } else {
            // gs.info("ryuki: entrou no else");
            return false;
        }

    },

    getGroupMembers: function(groupID) {
        var membersArray = [];
        var grGroupMember = new GlideRecord("sys_user_grmember");
        grGroupMember.addQuery("group", groupID);
        grGroupMember.query();
        while (grGroupMember.next()) {
            membersArray.push(grGroupMember.getValue('user'));
        }
        return membersArray.toString();
    },

    checkScheduleEntry: function() {
        var schedule = this.getParameter('sysparm_training_schedule');
        var userId = this.getParameter('sysparm_userid');
        var registered;
        var state;
        var trainingElegible;
        var vacanciesElegible;
        var instructorElegible;
        var dateElegible;
        var training;
        var instructorId;
        var today = new GlideDate();
        var trainingdate;
        var vacanciesRemaining = 0;

        var grSchedule = new GlideRecord("x_1092529_traini_0_training_schedule");
        grSchedule.get(schedule);
        if (grSchedule) {
            trainingdate = grSchedule.training_date;
            vacanciesRemaining = grSchedule.remaining_vacancies;
            training = grSchedule.training;
            instructorId = grSchedule.instructor.sys_id;
        }

        var grScheduleEntry = new GlideRecord("x_1092529_traini_0_inscription");
        grScheduleEntry.addEncodedQuery("training_schedule=" + schedule + "^user=" + userId);
        grScheduleEntry.query();

        //--------- Validação #7 ---------
        if (grScheduleEntry.next()) {
            registered = "true";
            state = grScheduleEntry.getDisplayValue("state");
        } else {
            registered = "false";
        }

        //--------- Validação #8 ---------
        var count = 0;
        //gs.info("ryuki training pre = " + training);
        var grInscription = new GlideRecord('x_1092529_traini_0_inscription');
        grInscription.addQuery('training_schedule.training', training);
        grInscription.addQuery('user', userId);
        grInscription.query();
        while (grInscription.next()) {
            count = count + 1;
        }
        if (count >= 3) {
            //gs.info("ryuki if training count = " + count);
            trainingElegible = "false";
        } else {
            //gs.info("ryuki else training = " + count);
            trainingElegible = "true";
        }

        //--------- Validação #9 ---------
        if (vacanciesRemaining > 0) {
            vacanciesElegible = "true";
        } else if (vacanciesRemaining <= 0) {
            vacanciesElegible = "false";
        }

        //--------- Validação 10 ---------

        if (userId == instructorId) {
            instructorElegible = "false";
        } else if (userId != instructorId) {
            instructorElegible = "true";
        }

        //--------- Validação 11 ---------
        if (today < trainingdate) {
            dateElegible = "true";
        } else {
            dateElegible = "false";
        }

        var results = {
            "registered": registered,
            "state": state,
            "training_elegible": trainingElegible,
            "vacancies_elegible": vacanciesElegible,
            "instructor_elegible": instructorElegible,
            "date_elegible": dateElegible
        };
        return JSON.stringify(results);
    },

    type: 'TrainingUtils'
});
